<div class="page-title">Review Schedule</div><p class="page-subtitle">Configure when Pre/Post Review reminders become active. Times use the selected timezone.</p>
<form method="post"><?=csrf_field()?><div class="review-grid"><div class="card"><h2>General</h2><p><label>Timezone</label><select name="timezone"><?php foreach(DateTimeZone::listIdentifiers() as $tz):?><option value="<?=e($tz)?>" <?=$settings['timezone']===$tz?'selected':''?>><?=e($tz)?></option><?php endforeach;?></select></p></div><div class="card"><h2>Day</h2><p><label>Pre Review start</label><input type="time" name="day_pre_time" value="<?=e(substr($settings['day_pre_time'],0,5))?>"></p><p><label>Post Review start</label><input type="time" name="day_post_time" value="<?=e(substr($settings['day_post_time'],0,5))?>"></p></div><div class="card"><h2>Week</h2><p><label>Pre Review day</label><select name="week_pre_day"><?php foreach([1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday',7=>'Sunday'] as $d=>$n):?><option value="<?=$d?>" <?=$settings['week_pre_day']==$d?'selected':''?>><?=$n?></option><?php endforeach;?></select></p><p><label>Pre Review time</label><input type="time" name="week_pre_time" value="<?=e(substr($settings['week_pre_time'],0,5))?>"></p><p><label>Post Review day</label><select name="week_post_day"><?php foreach([1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday',7=>'Sunday'] as $d=>$n):?><option value="<?=$d?>" <?=$settings['week_post_day']==$d?'selected':''?>><?=$n?></option><?php endforeach;?></select></p><p><label>Post Review time</label><input type="time" name="week_post_time" value="<?=e(substr($settings['week_post_time'],0,5))?>"></p></div><div class="card"><h2>Month</h2><p><label>Pre Review day</label><input type="number" min="1" max="31" name="month_pre_day" value="<?=e($settings['month_pre_day'])?>"></p><p><label>Pre Review time</label><input type="time" name="month_pre_time" value="<?=e(substr($settings['month_pre_time'],0,5))?>"></p><p><label>Post Review</label><span class="field-help">Last calendar day of the month.</span><input type="time" name="month_post_time" value="<?=e(substr($settings['month_post_time'],0,5))?>"></p></div><div class="card"><h2>Year</h2><p><label>Pre Review date</label><div class="grid"><input type="number" min="1" max="12" name="year_pre_month" value="<?=e($settings['year_pre_month'])?>"><input type="number" min="1" max="31" name="year_pre_day" value="<?=e($settings['year_pre_day'])?>"></div></p><p><label>Pre Review time</label><input type="time" name="year_pre_time" value="<?=e(substr($settings['year_pre_time'],0,5))?>"></p><p><label>Post Review date</label><div class="grid"><input type="number" min="1" max="12" name="year_post_month" value="<?=e($settings['year_post_month'])?>"><input type="number" min="1" max="31" name="year_post_day" value="<?=e($settings['year_post_day'])?>"></div></p><p><label>Post Review time</label><input type="time" name="year_post_time" value="<?=e(substr($settings['year_post_time'],0,5))?>"></p></div></div><div class="actions"><button>Save Schedule</button><a class="secondary-link" href="/pre-post-review">Open Reviews</a></div></form>
<style>.review-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}@media(max-width:800px){.review-grid{grid-template-columns:1fr}}</style>
